function sheetTableRows({ values }) {
  if (!Array.isArray(values) || values.some(row => !Array.isArray(row))) throw new Error('Expected the sheet range as rows of cell values');
  for (const row of values) for (const cell of row) if (cell !== null && typeof cell !== 'string' && typeof cell !== 'boolean' && !(typeof cell === 'number' && Number.isFinite(cell))) throw new Error('The sheet returned an invalid cell value');
  if (!values.length) return { rows: [] };
  const headers = values[0], rows = [];
  for (const cells of values.slice(1)) {
    const row = Object.create(null);
    for (let column = 0; column < cells.length; column++) {
      const header = headers[column];
      if (header) row[String(header)] = cells[column];
    }
    if (Object.keys(row).length) rows.push(row);
  }
  return { rows };
}

const items=$input.all();if(items.length===0)return [];if(items.length!==1)throw new Error("Expected one complete sheet range");return sheetTableRows({values:items[0].json.values}).rows.map(row=>({json:row}));
